 static void Toggle(Window window,ToolConfigurationState state,string name){var toggle=Visuals(window).OfType<ToggleButton>().Single(t=>t.DataContext is null&&t.Parent is Grid g&&g.Children.OfType<TextBlock>().Any(b=>b.Text==ConfigurationLocalization.ForLanguage("Chinese").Get(state.Find(name)!.CaptionKey)));toggle.IsChecked=toggle.IsChecked!=true;toggle.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}
 static void Write(string path,byte value){var image=BitmapSource.Create(4,4,96,96,PixelFormats.Gray8,null,Enumerable.Repeat(value,16).ToArray(),4);var encoder=new BmpBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(path);encoder.Save(stream);}
 static void Capture(Window window,string path){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var stream=File.Create(path);encoder.Save(stream);}
 static IEnumerable<DependencyObject> Visuals(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Visuals(VisualTreeHelper.GetChild(root,i)))yield return child;}
 sealed class Presentation:IToolConfigurationPresentationService{public List<ImageSourcePresentationMode> Modes=[];public ConfigurationPresentationResult Apply(ConfigurationPresentationRequest request){Modes.Add(request.SourceMode);return new(ConfigurationPresentationStatus.Supported);}}
 sealed class Subscriptions:IToolConfigurationSubscriptionService{public HashSet<string> ReadNames=[];public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery query)=>new(ConfigurationSubscriptionStatus.Available,[]);public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d){ReadNames.Add(d.Name);return new(ConfigurationSubscriptionStatus.Available,null,"");}public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? binding)=>new(ConfigurationSubscriptionStatus.Available,binding,binding is null?"":"source");}
